-- Hand-translated Supabase B triggers (see supabase-schema-b.json).
-- Versioned course tables get updated_at from the shim UPDATE itself (an AFTER
-- touch would re-fire the version guard).
CREATE TRIGGER IF NOT EXISTS "b_public__account_industry_profiles_set_updated_at" AFTER UPDATE ON "b_public__account_industry_profiles" FOR EACH ROW BEGIN UPDATE "b_public__account_industry_profiles" SET updated_at=strftime('%Y-%m-%dT%H:%M:%f+00:00','now') WHERE rowid=NEW.rowid; END;
