CREATE TRIGGER IF NOT EXISTS "b_public__course_appendices_enforce_version_update" BEFORE UPDATE ON "b_public__course_appendices" FOR EACH ROW WHEN NEW.version IS NOT OLD.version+1 BEGIN SELECT RAISE(ABORT,'stale course entity version'); END;
CREATE TRIGGER IF NOT EXISTS "b_public__course_assignments_enforce_version_update" BEFORE UPDATE ON "b_public__course_assignments" FOR EACH ROW WHEN NEW.version IS NOT OLD.version+1 BEGIN SELECT RAISE(ABORT,'stale course entity version'); END;
