CREATE TRIGGER IF NOT EXISTS "b_public__course_modules_enforce_version_update" BEFORE UPDATE ON "b_public__course_modules" FOR EACH ROW WHEN NEW.version IS NOT OLD.version+1 BEGIN SELECT RAISE(ABORT,'stale course entity version'); END;
CREATE TRIGGER IF NOT EXISTS "b_public__course_notes_enforce_version_update" BEFORE UPDATE ON "b_public__course_notes" FOR EACH ROW WHEN NEW.version IS NOT OLD.version+1 BEGIN SELECT RAISE(ABORT,'stale course entity version'); END;
CREATE TRIGGER IF NOT EXISTS "b_public__course_notes_validate_insert" BEFORE INSERT ON "b_public__course_notes" FOR EACH ROW WHEN NEW.lesson_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM "b_public__course_lessons" l JOIN "b_public__course_modules" m ON m.id=l.module_id JOIN "b_public__course_chapters" ch ON ch.id=m.chapter_id WHERE l.id=NEW.lesson_id AND ch.course_id=NEW.course_id) BEGIN SELECT RAISE(ABORT,'course note lesson does not belong to course'); END;
CREATE TRIGGER IF NOT EXISTS "b_public__course_notes_validate_update" BEFORE UPDATE ON "b_public__course_notes" FOR EACH ROW WHEN NEW.lesson_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM "b_public__course_lessons" l JOIN "b_public__course_modules" m ON m.id=l.module_id JOIN "b_public__course_chapters" ch ON ch.id=m.chapter_id WHERE l.id=NEW.lesson_id AND ch.course_id=NEW.course_id) BEGIN SELECT RAISE(ABORT,'course note lesson does not belong to course'); END;
CREATE TRIGGER IF NOT EXISTS "b_public__course_revisions_no_update" BEFORE UPDATE ON "b_public__course_revisions" FOR EACH ROW BEGIN SELECT RAISE(ABORT,'course revision history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS "b_public__course_revisions_no_delete" BEFORE DELETE ON "b_public__course_revisions" FOR EACH ROW BEGIN SELECT RAISE(ABORT,'course revision history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS "b_public__courses_enforce_version_update" BEFORE UPDATE ON "b_public__courses" FOR EACH ROW WHEN NEW.version IS NOT OLD.version+1 BEGIN SELECT RAISE(ABORT,'stale course entity version'); END;
